export function toCharacteristicScalarCborValue(v: CharacteristicScalar): CborValue {
  if (typeof v === "string") { const csilV = v as string; return [0, csilV]; }
  if (typeof v === "number" || typeof v === "bigint") { const csilV = v as number; return [1, csilV]; }
  if (typeof v === "boolean") { const csilV = v as boolean; return [2, csilV]; }
  throw new Error("unencodable CharacteristicScalar union value");
}

export function fromCharacteristicScalarCborValue(value: CborValue): CharacteristicScalar {
  const csilArr = asArray(value);
  if (csilArr.length !== 2) throw new Error(`CharacteristicScalar union expects a 2-element array, got ${csilArr.length}`);
  const csilIdx = asNumber(csilArr[0]);
  switch (csilIdx) {
    case 0: return asString(csilArr[1]);
    case 1: return asNumber(csilArr[1]);
    case 2: return asBool(csilArr[1]);
    default: throw new Error(`unknown CharacteristicScalar variant ${csilIdx}`);
  }
}

export function toCharacteristicScalarCbor(v: CharacteristicScalar): Uint8Array {
  return encodeValue(toCharacteristicScalarCborValue(v));
}

export function fromCharacteristicScalarCbor(bytes: Uint8Array): CharacteristicScalar {
  return fromCharacteristicScalarCborValue(decode(bytes));
}

export function toCharacteristicEntryCborValue(v: CharacteristicEntry): CborValue {
  const csilMap = new Map<CborValue, CborValue>();
  csilMap.set("key", v.key);
  csilMap.set("value", toCharacteristicScalarCborValue(v.value));
  return csilMap;
}

export function fromCharacteristicEntryCborValue(value: CborValue): CharacteristicEntry {
  return {
    key: asString(requireKey(value, "key")),
    value: fromCharacteristicScalarCborValue(requireKey(value, "value")),
  };
}

export function toCharacteristicEntryCbor(v: CharacteristicEntry): Uint8Array {
  return encodeValue(toCharacteristicEntryCborValue(v));
}

export function fromCharacteristicEntryCbor(bytes: Uint8Array): CharacteristicEntry {
  return fromCharacteristicEntryCborValue(decode(bytes));
}

export function toWorkerCharacteristicValueCborValue(v: WorkerCharacteristicValue): CborValue {
  if (typeof v === "string") { const csilV = v as string; return [0, csilV]; }
  if (typeof v === "number" || typeof v === "bigint") { const csilV = v as number; return [1, csilV]; }
  if (typeof v === "boolean") { const csilV = v as boolean; return [2, csilV]; }
  if (Array.isArray(v)) { const csilV = v as string[]; return [3, csilV]; }
  if (Array.isArray(v)) { const csilV = v as number[]; return [4, csilV]; }
  if (Array.isArray(v)) { const csilV = v as boolean[]; return [5, csilV]; }
  throw new Error("unencodable WorkerCharacteristicValue union value");
}

export function fromWorkerCharacteristicValueCborValue(value: CborValue): WorkerCharacteristicValue {
  const csilArr = asArray(value);
  if (csilArr.length !== 2) throw new Error(`WorkerCharacteristicValue union expects a 2-element array, got ${csilArr.length}`);
  const csilIdx = asNumber(csilArr[0]);
  switch (csilIdx) {
    case 0: return asString(csilArr[1]);
    case 1: return asNumber(csilArr[1]);
    case 2: return asBool(csilArr[1]);
    case 3: return asArray(csilArr[1]).map((csilE) => asString(csilE));
    case 4: return asArray(csilArr[1]).map((csilE) => asNumber(csilE));
    case 5: return asArray(csilArr[1]).map((csilE) => asBool(csilE));
    default: throw new Error(`unknown WorkerCharacteristicValue variant ${csilIdx}`);
  }
}

export function toWorkerCharacteristicValueCbor(v: WorkerCharacteristicValue): Uint8Array {
  return encodeValue(toWorkerCharacteristicValueCborValue(v));
}

export function fromWorkerCharacteristicValueCbor(bytes: Uint8Array): WorkerCharacteristicValue {
  return fromWorkerCharacteristicValueCborValue(decode(bytes));
}

